    const autoPossible=['douyin','xiaohongshu','bilibili'].includes(c?.platform)&&Boolean(c?.rawUrl);
    const status=c?.manualSummary?'你的手动总结 · 原视频已保留':c?.videoAnalysis?.provider==='bailian_omni_video_url'?`长视频 Omni 音画摘要 · ${c?.videoAnalysis?.frameCapture?.cached?`已取 ${c.videoAnalysis.frameCapture.cached} 帧`:'未取到帧'}，待核对`:c?.videoAnalysis?.provider==='bailian_video_url'?'长视频 AI 画面摘要 · 无截图，待核对':c?.ingestStatus==='queued'?'云端正在读取视频内容':c?.cardDraft?'知识卡草稿待核对':c?.ingestStatus==='transcribed'&&c?.transcript?.model==='platform-subtitle'&&!c?.videoEvidence?.length?'仅取得平台字幕，未完成画面理解':c?.ingestStatus==='transcribed'?(c?.imageAnalysis?'抖音图文已分析 · 待核对':c?.videoAnalysis?'视频已解析':'视频已转成文字'):c?.ingestStatus==='failed'?'自动整理未完成':hasText?'有来源文字':'待补充内容';
    const notebook=notebookReadModel(shown,c||{});
    const actionSegments=Array.isArray(c?.actionSegments)?c.actionSegments:[];
