    const omniSegmentsHTML=omniEvidence.length?`<details class="video-action-segments omni-action-segments" ${typeOf(k)!=='follow_along'?'open':''}><summary>Omni 时间分段与动作提取（${omniEvidence.length} 段）</summary><p class="small muted">这些时间段是 AI 对整段声画的摘要，不是逐字稿。可用时会显示从原视频解码保存的代表帧；云端预览按本任务保留 ${previewDaysFor(c)} 天；保存动作前仍请打开原视频核对，动作默认仅手动使用。</p>${omniEvidence.map(item=>`<section class="video-action-segment"><div class="video-action-time">${time(item.startMs)}–${time(item.endMs)}</div>${notebookPointsHTML(notebook.omniPoints.get(`vision:${c.videoEvidence.indexOf(item)}`)||[])}<span class="badge warm">Omni 音画摘要 · 待核对</span>${item.thumbnail?`<img class="video-action-image" data-frame-capture="${esc(c.id)}" data-frame-segment="${esc(item.id)}" alt="${time(item.frameAtMs)} 视频帧" loading="lazy">`: `<p class="small muted">${item.frameStatus==='extractor_unavailable'?'暂未取得截图；分段摘要仍可查看。':item.frameStatus==='timeout'?'该段取帧超时；可打开原视频核对。':'这段暂时没有可用的代表帧。'}</p>`}<details class="notebook-observation"><summary>查看音画记录</summary><p>${esc(item.text)}</p></details><button class="text-button orange" data-extract-omni-segment="${esc(k.id)}" data-evidence-id="${esc(item.id)}">核对并从这一段提取动作 ${icon('arrow')}</button><button class="text-button" data-manual-activity="${esc(c.id)}" data-source-type="omni" data-source-id="${esc(item.id)}">自己填写动作</button></section>`).join('')}</details>`:'';
    const imageEvidence=Array.isArray(c?.imageEvidence)?c.imageEvidence:[];
