    const liveVideoEvidence=Array.isArray(c?.liveVideoEvidence)?c.liveVideoEvidence:[];
    const liveVideoEvidenceHTML=liveVideoEvidence.length?`<details class="video-action-segments live-photo-videos"><summary>图文动态小视频（${liveVideoEvidence.length} 项）</summary><p class="small muted">每段视频由 AI 单独观察；对应原图用于帮助辨认，不是视频抽帧。动态观察待你核对，不是作者原话。模型调用 ${liveVideoEvidence.filter(x=>x.modelInvoked).length} 次。</p>${liveVideoEvidence.map(item=>{const cover=item.coverThumbnail||imageEvidence.find(x=>x.imageIndex===item.imageIndex)?.thumbnail,status=item.status==='analyzed'?`动态观察：${item.text}`:({skipped:item.reason==='duration_unsupported'?'该段没有受支持的时长；未送入模型。':item.reason==='no_video_address'?'没有可读取的小视频地址。':item.reason==='live_video_too_large'?'小视频文件超过处理限制。':'暂未成功分析；静态图和原始链接仍保留。',failed:item.reason==='media_unavailable'?'无法读取这段小视频；静态图仍可查看。':'该段小视频分析失败；静态图仍可查看。'}[item.status]||'这项动态内容暂不可用。');return `<section class="video-action-segment"><div class="video-action-time">图文第 ${item.imageIndex+1} 项${item.durationMs!=null?` · ${(item.durationMs/1000).toFixed(1)} 秒`:''}</div>${notebookPointsHTML(notebook.imagePoints.get(`live-video:${item.imageIndex}`)||[])}${cover?`<img class="video-action-image" data-capture-image="${esc(c.id)}" data-image-index="${item.imageIndex}" alt="第 ${item.imageIndex+1} 项对应的原图" loading="lazy">`:'<p class="small muted">没有可用的对应原图。</p>'}${item.status==='analyzed'?'<span class="badge warm">AI 动态画面观察 · 待核对</span>':''}<p>${esc(status)}</p>${item.status==='analyzed'?`<button class="text-button orange" data-extract-image="${esc(k.id)}" data-image-index="${item.imageIndex}" data-live-video="true">核对并从这段视频提取动作 ${icon('arrow')}</button>`:''}<button class="text-button" data-manual-activity="${esc(c.id)}" data-source-type="image" data-image-index="${item.imageIndex}">自己填写动作</button></section>`;}).join('')}</details>`:'';
    const queued=c?.ingestStatus==='queued',tooLong=c?.ingestErrorCode==='too_long',badTranscript=needsVisualReview(c);
    const reviewButton=c?.cardDraft?`<button class="primary" data-review-ingest="${esc(c.id)}">${k.status==='saved'?'核对更新':'核对知识卡'} ${icon('arrow')}</button>`:'';
    const actions=queued?'<span class="small muted" role="status">后台处理中；离开页面后可回来查看</span>'
      :reviewButton|| (badTranscript&&autoPossible?`<button class="primary" data-auto-ingest="${esc(c.id)}" data-force-ingest="true">重新解析画面 ${icon('arrow')}</button>`:tooLong?`<button class="primary" data-manual-video-summary="${esc(c.id)}">${c.manualSummary?'编辑我的总结':'自己整理这条视频'} ${icon('edit')}</button>`
      :k.status==='saved'?''
      :autoPossible&&c.ingestStatus!=='transcribed'?`<button class="primary" data-auto-ingest="${esc(c.id)}" ${c.ingestStatus==='failed'?'data-force-ingest="true"':''}>${c.ingestStatus==='failed'?'重试自动整理':'开始整理'} ${icon('arrow')}</button>`
      :hasText?`<button class="primary" data-analyze-capture="${esc(c.id)}">整理知识草稿 ${icon('arrow')}</button>`
      :c?`<button class="primary" data-edit-capture="${esc(c.id)}">补充内容 ${icon('edit')}</button>`
      :k.status==='inbox'?`<button class="primary" data-save-knowledge="${esc(k.id)}">收进个人库 ${icon('check')}</button>`:'');
    const moreActions=queued?'':tooLong?`<button class="text-button" data-copy-video-url="${esc(c.id)}">复制视频链接</button>`:
      `${autoPossible&&(k.status==='saved'||c.ingestStatus==='transcribed'||c.cardDraft)?`<button class="text-button" data-auto-ingest="${esc(c.id)}" data-force-ingest="true">${c?.imageAnalysis?'重新分析图文':'重新解析视频'}</button>`:''}${hasText?`<button class="text-button" data-analyze-capture="${esc(c.id)}">${c?.imageAnalysis?'用已有图像观察整理':'只用现有文字整理'}</button>`:''}${c?`<button class="text-button" data-edit-capture="${esc(c.id)}">补充来源内容</button>`:''}`;
    const planDetail=shown.planPoints?.length?`<section class="notebook-plan"><div class="notebook-section-heading"><span>方案大纲</span><h3>来源里的训练安排（${shown.planPoints.length}）</h3></div><p class="small muted">这是来源方案，不是你的个人训练计划；安排训练时仍需按当天条件调整。</p>${shown.planPoints.map(p=>`<div class="plan-outline-row"><strong>${esc(PLAN_POINT_KINDS[p.kind]||'方案内容')}</strong><span>${esc(p.text)}</span>${sourceQuoteHTML(p)}</div>`).join('')}</section>`:'';
