    const dates=`<dl class="knowledge-dates"><div><dt>添加日期</dt><dd>${added.iso?`<time datetime="${esc(added.iso)}">${esc(added.text)}</time>`:added.text}</dd></div>${k.updatedAt&&k.updatedAt!==k.createdAt&&Number.isFinite(new Date(k.updatedAt).getTime())?`<div><dt>最近修改</dt><dd>${esc(new Date(k.updatedAt).toLocaleString("zh-CN",{year:"numeric",month:"long",day:"numeric",hour:"2-digit",minute:"2-digit",hour12:false}))}</dd></div>`:""}</dl>`;
    const sourceLink=safeURL(sourceUrl)?`<a class="text-button" href="${esc(safeURL(sourceUrl))}" target="_blank" rel="noopener noreferrer">${kindOf(k)==="video"?"打开原视频":kindOf(k)==="image_post"?"打开原图文":"打开来源"} ${icon("arrow")}</a>`:"";
    const claimsHTML=notebookPointsHTML(notebook.unattached);
    const transcript=c?.transcript?.text?`<details><summary>${c.transcript.model==="platform-subtitle"?"查看平台字幕":c.ingestStatus==="failed"?"查看上次视频逐字稿":"查看视频逐字稿"}</summary><p class="small muted">${c.transcript.model==='platform-subtitle'?'平台字幕也可能包含背景音乐歌词，不能代表视频画面已解析。':'自动语音识别可能有误，请结合原视频核对。'}</p><p>${esc(c.transcript.text)}</p></details>${badTranscript?'<p class="knowledge-update-note">这些文字疑似歌词或重复噪声，未用作动作或训练知识依据；请重新读取画面。</p>':''}`:"";
